/* Datum service worker — generated by esbuild.web.mjs. Do not edit dist/sw.js. */
const VERSION = "__VERSION__";
const CACHE = `step-viewer-${VERSION}`;
// Big, rarely-changing assets (the 2D viewer bundle, its workers and the
// LibreDWG wasm) live in one long-lived cache keyed by their own content hash
// (the ?v= query), so an app update doesn't re-download an unchanged wasm.
const ASSETS = "step-viewer-assets";
// Fonts for DWG/DXF text are fetched from mlightcad's cad-data repo on
// jsDelivr; cache what gets used so drawings render offline afterwards.
const FONT_ORIGIN = "https://cdn.jsdelivr.net";
const FONT_PATH = "/gh/mlightcad/cad-data";
const PRECACHE = __PRECACHE__;
const LAZY = __LAZY__;

const scopeUrl = new URL(self.registration.scope);
const toUrl = (p) => new URL(p, scopeUrl).href;
const stripQuery = (u) => {
  const x = new URL(u);
  x.search = "";
  return x.href;
};

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) =>
      Promise.all(
        PRECACHE.map((p) =>
          // cache: "reload" bypasses the HTTP cache so a deploy is picked up
          // even when the host sends long max-age headers.
          cache.add(new Request(toUrl(p), { cache: "reload" })),
        ),
      ),
    ),
  );
  // No skipWaiting() here on purpose: the page shows "Update available" and
  // asks; it sends SKIP_WAITING when the user accepts.
});

/** Fetch the lazy assets in the background; drop stale versions. */
async function refreshLazyAssets() {
  const cache = await caches.open(ASSETS);
  const wanted = new Map(LAZY.map((p) => [stripQuery(toUrl(p)), toUrl(p)]));
  // Purge entries whose path is ours but whose ?v= no longer matches.
  for (const req of await cache.keys()) {
    const bare = stripQuery(req.url);
    if (wanted.has(bare) && wanted.get(bare) !== req.url) await cache.delete(req);
  }
  for (const [, url] of wanted) {
    if (await cache.match(url)) continue;
    try {
      const res = await fetch(new Request(url, { cache: "reload" }));
      if (res.ok) await cache.put(url, res);
    } catch {
      /* offline — try again next activation / on demand */
    }
  }
}

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((k) => k.startsWith("step-viewer-") && k !== CACHE && k !== ASSETS).map((k) => caches.delete(k))),
      )
      .then(() => self.clients.claim())
      .then(() => refreshLazyAssets()),
  );
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
  if (event.data && event.data.type === "GET_VERSION") event.source?.postMessage({ type: "VERSION", version: VERSION });
  if (event.data && event.data.type === "PREFETCH_ASSETS") event.waitUntil?.(refreshLazyAssets());
});

/** Cache-first against the assets cache, ignoring ?v= on lookup. */
async function assetResponse(req) {
  const cache = await caches.open(ASSETS);
  const hit = await cache.match(req, { ignoreSearch: true });
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok) {
    // Store under the versioned URL from LAZY when we know it, so the entry
    // is recognised (and purged) by refreshLazyAssets.
    const bare = stripQuery(req.url);
    const key = LAZY.map((p) => toUrl(p)).find((u) => stripQuery(u) === bare) ?? req.url;
    cache.put(key, res.clone());
  }
  return res;
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);

  // Font / template data for the 2D viewer: cache-first, kept across updates.
  if (url.origin === FONT_ORIGIN && url.pathname.startsWith(FONT_PATH)) {
    event.respondWith(
      caches.open(ASSETS).then(async (cache) => {
        const hit = await cache.match(req);
        if (hit) return hit;
        const res = await fetch(req);
        if (res.ok) cache.put(req, res.clone());
        return res;
      }),
    );
    return;
  }
  if (url.origin !== location.origin) return;

  // App shell for navigations (works offline, and file-handler launches).
  if (req.mode === "navigate") {
    event.respondWith(
      caches.open(CACHE).then(async (cache) => {
        const cached = await cache.match(toUrl("index.html"), { ignoreSearch: true });
        if (cached) return cached;
        try {
          return await fetch(req);
        } catch {
          return new Response("Offline and not cached yet.", { status: 503, headers: { "Content-Type": "text/plain" } });
        }
      }),
    );
    return;
  }

  // Lazy 2D assets (cad2d.js, workers/*).
  const rel = url.pathname.startsWith(scopeUrl.pathname) ? url.pathname.slice(scopeUrl.pathname.length) : null;
  if (rel !== null && (rel === "cad2d.js" || rel.startsWith("workers/"))) {
    event.respondWith(assetResponse(req));
    return;
  }

  // Versioned shell assets: cache-first (the cache name changes with every build).
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const cached = await cache.match(req, { ignoreSearch: true });
      if (cached) return cached;
      const res = await fetch(req);
      if (res.ok && rel !== null) cache.put(req, res.clone());
      return res;
    }),
  );
});
